"""Small same-origin operator form; no publication endpoint."""
PANEL = '''<section id="resolution"><h2>Résoudre l'identité</h2>
<p>Les preuves restent locales. La décision sera appliquée par le cycle normal.</p>
<button id="open-resolution">Examiner ce fichier</button><div id="resolution-form" hidden>
<p id="resolution-status"></p><h3>Variantes connues et sélection actuelle</h3><pre id="resolution-variants"></pre><pre id="resolution-current"></pre>
<label>Candidat ou édition locale <select id="resolution-candidate"></select></label>
<p><input id="resolution-query" placeholder="Titre, auteur ou ISBN"><button id="resolution-search">Rechercher</button></p>
<p><label>Ouvrage pour une nouvelle édition <select id="resolution-work"></select></label></p><pre id="resolution-notice"></pre><div id="resolution-fields"></div>
<p><label><input id="resolution-edit-shared" type="checkbox">Corriger explicitement les métadonnées partagées affichées</label></p>
<p><label><input id="resolution-select" type="checkbox">Sélectionner ce fichier pour cette édition</label></p>
<p><input id="resolution-page-number" type="number" min="1" value="1"><button id="resolution-page">Lire une page justificative</button></p>
<div id="resolution-pages"></div>
<p>Relier chaque champ qui distingue cette édition à une page et à une mention lisible.</p>
<div id="resolution-proof"></div><button id="resolution-add-proof">Ajouter une concordance</button>
<p><textarea id="resolution-reason" maxlength="4000" placeholder="Justification et réponse aux contradictions"></textarea></p>
<p><label>Décision bloquée à remplacer <input id="resolution-supersedes"></label></p>
<p><label>Révision de récupération à restaurer <select id="resolution-restore"></select></label></p>
<p><button id="work-preview">Prévisualiser l’album sans édition</button><button id="work-confirm" disabled>Confirmer cet album</button></p>
<button id="resolution-preview">Prévisualiser</button><pre id="resolution-effect"></pre>
<button id="resolution-confirm" disabled>Confirmer cette décision</button></div></section>
<script>
(()=>{const $=id=>document.getElementById(id);let token,asset,caseData,choices=[],pages=[],preview,requestId,workPreview;
const names=['title','author','series','number','publisher','language','date','revision','isbn','reference'];
async function post(action,data){const r=await fetch('/api/resolution/'+action,{method:'POST',headers:{'Content-Type':'application/json','Origin':location.origin,'X-CSRF-Token':token},body:JSON.stringify(data)});const value=await r.json();if(!r.ok)throw Error(value.reason||r.status);return value}
function status(t){$('resolution-status').textContent=t}
function invalidate(){workPreview=null;$('work-confirm').disabled=true;preview=null;$('resolution-confirm').disabled=true}
function options(){const select=$('resolution-candidate');select.replaceChildren();for(let i=0;i<choices.length;i++){const o=document.createElement('option');o.value=i;o.textContent=choices[i].label;select.append(o)}}
function chosen(){invalidate();const c=choices[Number($('resolution-candidate').value)]||{};for(const k of names)$('resolution-'+k).value=(c.work||{})[k]||(c.edition||{})[k]||'';caseData.chosen=c;$('resolution-notice').textContent=JSON.stringify(c.notice||{},null,2);$('resolution-variants').textContent=JSON.stringify(Object.fromEntries(Object.entries(caseData.variants).filter(([id,v])=>!c.edition_id||v.edition===c.edition_id)),null,2)}
function addProof(){const row=document.createElement('p');const field=document.createElement('select');field.className='proof-field';for(const k of names){const o=document.createElement('option');o.value=k;o.textContent=k;field.append(o)}const page=document.createElement('select');page.className='proof-page';for(const p of pages){const o=document.createElement('option');o.value=p.id;o.textContent='Page '+p.page;page.append(o)}const text=document.createElement('input');text.className='proof-text';text.maxLength=1000;text.placeholder='Mention lue';row.append(field,page,text);$('resolution-proof').append(row);invalidate()}
$('open-resolution').onclick=async()=>{try{const r=await fetch('/api/resolution/token');token=(await r.json()).token;const origin=location.pathname.split('/').pop();caseData=await post('case',{origin});asset=caseData.asset;$('resolution-form').hidden=false;$('resolution-current').textContent=JSON.stringify({identity:caseData.identity,publication:caseData.publications,decision:caseData.resolution,unknowns:caseData.unknowns},null,2);choices=[{label:'Saisir une autre édition',work:{},edition:{}},...caseData.editions,...caseData.candidates];options();const work=$('resolution-work');work.replaceChildren();for(const v of [{id:'',label:'Créer un ouvrage'},...caseData.works]){const o=document.createElement('option');o.value=v.id;o.textContent=v.label;work.append(o)}const restore=$('resolution-restore');restore.replaceChildren();for(const value of [{id:'',label:'Aucune restauration'},...caseData.recovery]){const o=document.createElement('option');o.value=value.id;o.textContent=value.label;restore.append(o)}$('resolution-variants').textContent=JSON.stringify(caseData.variants,null,2);status('Choisir une édition et ses preuves. Les champs absents restent inconnus.')}catch(e){status(String(e))}};
for(const k of names){const label=document.createElement('label');label.textContent=k+' ';const input=document.createElement('input');input.id='resolution-'+k;input.maxLength=500;label.append(input);$('resolution-fields').append(label)}
$('resolution-candidate').onchange=chosen;
$('resolution-work').onchange=()=>{invalidate();const w=caseData.works.find(w=>w.id===$('resolution-work').value);if(w)for(const [k,v] of Object.entries(w.fields))$('resolution-'+k).value=v};
$('resolution-search').onclick=async()=>{try{status('Recherche bornée en cours…');const found=await post('search',{query:$('resolution-query').value});choices=[choices[0],...caseData.editions,...found.candidates];options();status(found.reason||'Choisir une édition. Une proposition ne confirme rien.')}catch(e){status(String(e))}};
$('resolution-page').onclick=async()=>{try{const p=await post('page',{asset,page:Number($('resolution-page-number').value)});pages.push(p);const img=document.createElement('img');img.src='/api/resolution/proof/'+p.id;img.alt='Page '+p.page;img.style.maxWidth='100%';$('resolution-pages').append(img);addProof();status('Vérifier la lisibilité puis transcrire les mentions.')}catch(e){status(String(e))}};
$('resolution-add-proof').onclick=addProof;
$('resolution-preview').onclick=async()=>{try{const c=caseData.chosen||{},work={},edition={};for(const k of names){const v=$('resolution-'+k).value;if(v)(['title','author','series','number'].includes(k)?work:edition)[k]=v}const proof=Array.from($('resolution-proof').children).map(row=>({page:row.querySelector('.proof-page').value,field:row.querySelector('.proof-field').value,text:row.querySelector('.proof-text').value}));preview=await post('preview',{asset,values:{edition_id:c.edition_id||null,work_id:c.work_id||$('resolution-work').value||null,work,edition,select:$('resolution-select').checked,edit_shared:$('resolution-edit-shared').checked,proof,reason:$('resolution-reason').value,supersedes:$('resolution-supersedes').value||null,restore:$('resolution-restore').value||null,candidate:c.candidate||null}});$('resolution-effect').textContent=JSON.stringify(preview,null,2);requestId=crypto.randomUUID();$('resolution-confirm').disabled=false}catch(e){status(String(e))}};
$('work-preview').onclick=()=>{try{if(caseData.identity)throw Error('Résoudre l’édition existante avant de confirmer un album.');const work={};for(const k of ['title','author','series','number']){const v=$('resolution-'+k).value.trim();if(v)work[k]=v}if(!work.title)throw Error('Le titre est requis.');const proof=Array.from($('resolution-proof').children).map(row=>({page:row.querySelector('.proof-page').value,text:row.querySelector('.proof-text').value}));workPreview={asset,...caseData.work_case,request_id:crypto.randomUUID(),work,proof,reason:$('resolution-reason').value};$('resolution-effect').textContent=JSON.stringify({effect:'Identifier l’album; édition inconnue; classement au prochain cycle',...workPreview},null,2);$('work-confirm').disabled=false}catch(e){status(String(e))}};
$('work-confirm').onclick=async()=>{if(!workPreview)return;try{const result=await post('confirm-work',workPreview);status('Album confirmé : '+result.decision+'. Classement au prochain cycle.');invalidate()}catch(e){status(String(e))}};
$('resolution-confirm').onclick=async()=>{if(!preview)return;try{const result=await post('confirm',{preview:preview.id,request_id:requestId});status('Décision enregistrée : '+result.decision+'. Application au cycle normal.');$('resolution-confirm').disabled=true}catch(e){status(String(e))}};
$('resolution-form').addEventListener('input',invalidate);
})();</script>'''
